create table if not exists public.character_activities(character_id uuid primary key references public.characters(id) on delete cascade, activity_id text not null, started_at timestamptz not null, last_claim_at timestamptz not null, state_version bigint not null default 1, metadata jsonb not null default '{}');
create table if not exists public.character_skills(character_id uuid not null references public.characters(id) on delete cascade, skill_id text not null, level integer not null default 1, xp bigint not null default 0, primary key(character_id,skill_id));
create table if not exists public.crafting_jobs(id uuid primary key default gen_random_uuid(), character_id uuid not null references public.characters(id), recipe_id text not null, quantity integer not null check(quantity>0), completes_at timestamptz not null, status text not null check(status in('active','completed','claimed','cancelled')), idempotency_key text not null unique, created_at timestamptz not null default now());
alter table public.character_activities enable row level security; alter table public.character_skills enable row level security; alter table public.crafting_jobs enable row level security;
create policy "owner reads activities" on public.character_activities for select using(character_id in(select id from public.characters where account_id=auth.uid()));
create policy "owner reads skills" on public.character_skills for select using(character_id in(select id from public.characters where account_id=auth.uid()));
create policy "owner reads crafts" on public.crafting_jobs for select using(character_id in(select id from public.characters where account_id=auth.uid()));
